// Turn toward the hand's movement. In Three.js a positive yaw looks left,
// while a natural trackpad scroll reports the opposite sign to finger motion.
export function exhibitionLookInput(pose, dx, dy, { wheel = false, unit = 1, minPitch = -.65, maxPitch = .65 } = {}) {
  const clamp = (value, low, high) => Math.max(low, Math.min(high, value));
  const x = wheel ? clamp(dx * unit, -180, 180) : dx;
  const y = wheel ? clamp(dy * unit, -180, 180) : dy;
  return {
    yaw: pose.yaw + x * (wheel ? .0025 : -.003),
    pitch: clamp(pose.pitch + y * (wheel ? .002 : -.0025), minPitch, maxPitch),
  };
}
